INSERT INTO public.guide (map_id, title, body, source_url)
SELECT m.id, #{title}, #{body}, #{sourceUrl,jdbcType=VARCHAR}
FROM public.travel_map m
WHERE m.id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.user_account a
      WHERE a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING

UPDATE public.guide g
SET title = #{title},
    body = #{body},
    source_url = #{sourceUrl,jdbcType=VARCHAR},
    updated_at = CASE
        WHEN g.title IS DISTINCT FROM #{title}
          OR g.body IS DISTINCT FROM #{body}
          OR g.source_url IS DISTINCT FROM #{sourceUrl,jdbcType=VARCHAR}
        THEN clock_timestamp()
        ELSE g.updated_at
    END
WHERE g.id = #{guideId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND g.map_id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
